 s.prefs = {theme:p.theme === 'night' ? 'night' : 'paper',font:[16,18,20,22].includes(p.font) ? p.font : 18,mode:['full','recall','spell'].includes(p.mode) ? p.mode : 'full',panel:p.panel !== false,rate:[.85,1,1.2].includes(p.rate) ? p.rate : 1};
 s.sessions = Array.isArray(raw.sessions) ? raw.sessions.filter(x => x && ['spell','listen'].includes(x.mode) && Number.isInteger(x.total) && x.total > 0 && x.total <= 47 && Number.isInteger(x.correct) && x.correct >= 0 && x.correct <= x.total && Number.isFinite(x.at)).slice(-100) : [];
 s.visited=raw.visited===true||s.lastChapter>0||s.completed.length>0; s.reading=cleanPositions(raw.reading); s.listening=cleanListening(raw.listening); Object.assign(s.prefs,cleanExtraPrefs(raw.prefs)); s.updatedAt = Number.isFinite(raw.updatedAt) ? raw.updatedAt : null; return s;
